+    "formatVersion": {
+      "const": "0.5.0"
+    },
+    "vaoId": {
+      "$ref": "#/$defs/id"
+    },
+    "releaseId": {
+      "$ref": "#/$defs/id"
+    },
+    "revision": {
+      "type": "integer",
+      "minimum": 1,
+      "maximum": 9007199254740991
+    },
+    "contentVersion": {
+      "type": "string",
+      "minLength": 1
+    },
+    "publication": {
+      "$ref": "#/$defs/publication"
+    }
+  },
+  "additionalProperties": false,
+  "$defs": {
+    "id": {
+      "type": "string",
+      "pattern": "^(urn:|https?:)[^\\s]+$"
+    },
+    "sha256": {
+      "type": "string",
+      "pattern": "^[0-9a-f]{64}$"
