+        },
+        "role": {
+          "enum": [
+            "manifest",
+            "carrier",
+            "realization",
+            "pack",
+            "pack-manifest",
+            "checksum",
+            "documentation",
+            "metadata",
+            "preview",
+            "other"
+          ]
+        },
+        "byteSize": {
+          "type": "integer",
+          "minimum": 0,
+          "maximum": 9007199254740991
+        },
+        "sha256": {
+          "$ref": "#/$defs/sha256"
+        },
+        "realizationIds": {
+          "type": "array",
+          "minItems": 1,
+          "uniqueItems": true,
+          "items": {
+            "$ref": "#/$defs/id"
+          }
+        },
+        "carrierId": {
+          "$ref": "#/$defs/id"
+        },
+        "carrierMode": {
+          "enum": [
+            "bootstrap",
+            "preservation-closure",
+            "custom"
+          ]
+        },
+        "manifestSHA256": {
+          "$ref": "#/$defs/sha256"
+        },
+        "manifestByteSize": {
+          "type": "integer",
+          "minimum": 1,
+          "maximum": 9007199254740991
+        },
+        "carrierDescriptorSHA256": {
+          "$ref": "#/$defs/sha256"
+        },
+        "carrierDescriptorByteSize": {
+          "type": "integer",
+          "minimum": 1,
+          "maximum": 9007199254740991
+        },
+        "completeGroupIds": {
+          "type": "array",
+          "uniqueItems": true,
+          "items": {
+            "$ref": "#/$defs/id"
+          }
+        }
+      },
+      "additionalProperties": false,
+      "allOf": [
+        {
+          "if": {
+            "properties": {
+              "role": {
