+          },
+          "then": {
+            "required": [
+              "realizationIds"
+            ]
+          }
+        },
+        {
+          "if": {
+            "properties": {
+              "role": {
+                "const": "carrier"
+              }
+            },
+            "required": [
+              "role"
+            ]
+          },
+          "then": {
+            "required": [
+              "carrierId",
+              "carrierMode",
+              "manifestSHA256",
+              "manifestByteSize",
+              "carrierDescriptorSHA256",
+              "carrierDescriptorByteSize",
+              "completeGroupIds"
+            ]
+          }
+        }
+      ]
+    },
+    "record": {
+      "type": "object",
+      "required": [
+        "id",
+        "repositoryType",
+        "instance",
+        "versionPersistentIdentifier",
+        "recordIdentifier",
+        "files"
+      ],
+      "properties": {
+        "id": {
+          "$ref": "#/$defs/id"
+        },
+        "repositoryType": {
+          "type": "string",
+          "format": "uri"
+        },
+        "instance": {
+          "type": "string",
+          "format": "uri"
+        },
+        "versionPersistentIdentifier": {
+          "type": "string",
+          "format": "uri"
+        },
+        "conceptPersistentIdentifier": {
+          "type": "string",
+          "format": "uri"
+        },
+        "recordIdentifier": {
+          "type": "string",
+          "minLength": 1
+        },
+        "files": {
+          "type": "array",
+          "minItems": 1,
+          "items": {
+            "$ref": "#/$defs/recordFile"
+          }
+        }
+      },
+      "additionalProperties": false
+    },
+    "familyMember": {
+      "type": "object",
+      "required": [
+        "recordRole",
+        "membership",
+        "relationFromRoot",
+        "record"
+      ],
+      "properties": {
+        "recordRole": {
+          "enum": [
+            "asset-pack",
+            "rights-partition",
+            "access-partition",
+            "preservation",
+            "documentation",
+            "mirror",
+            "other"
+          ]
+        },
+        "membership": {
+          "enum": [
+            "exclusive",
+            "shared"
+          ]
+        },
+        "relationFromRoot": {
+          "enum": [
+            "hasPart",
+            "requires",
+            "references",
+            "isSupplementedBy",
+            "isDocumentedBy",
+            "isDerivedFrom"
+          ]
+        },
+        "inverseRelationFromMember": {
+          "enum": [
+            "isPartOf",
+            "isRequiredBy",
+            "isReferencedBy",
+            "isSupplementTo",
+            "documents",
+            "isSourceOf"
+          ]
+        },
+        "record": {
+          "$ref": "#/$defs/record"
+        }
+      },
+      "additionalProperties": false,
+      "allOf": [
+        {
+          "if": {
+            "properties": {
+              "membership": {
+                "const": "exclusive"
+              }
+            },
+            "required": [
+              "membership"
+            ]
+          },
+          "then": {
+            "properties": {
+              "relationFromRoot": {
+                "const": "hasPart"
+              },
+              "inverseRelationFromMember": {
+                "const": "isPartOf"
+              }
+            },
+            "required": [
+              "inverseRelationFromMember"
+            ]
+          }
+        },
+        {
+          "if": {
+            "properties": {
+              "membership": {
+                "const": "shared"
+              }
+            },
+            "required": [
+              "membership"
+            ]
+          },
+          "then": {
+            "properties": {
+              "relationFromRoot": {
+                "enum": [
+                  "requires",
+                  "references",
+                  "isSupplementedBy",
+                  "isDocumentedBy",
+                  "isDerivedFrom"
+                ]
+              }
+            }
+          }
+        }
+      ]
+    },
+    "publication": {
+      "type": "object",
+      "required": [
+        "topology",
+        "rootRecord",
+        "familyMembers"
+      ],
+      "properties": {
+        "topology": {
+          "enum": [
+            "single-record",
+            "record-family"
+          ]
+        },
+        "rootRecord": {
+          "$ref": "#/$defs/record"
+        },
+        "familyMembers": {
+          "type": "array",
+          "items": {
+            "$ref": "#/$defs/familyMember"
+          }
+        }
+      },
+      "additionalProperties": false,
+      "allOf": [
+        {
+          "if": {
+            "properties": {
+              "topology": {
+                "const": "single-record"
+              }
+            },
+            "required": [
+              "topology"
+            ]
+          },
+          "then": {
+            "properties": {
+              "familyMembers": {
+                "maxItems": 0
+              }
+            }
+          }
+        },
+        {
+          "if": {
+            "properties": {
+              "topology": {
+                "const": "record-family"
+              }
+            },
+            "required": [
+              "topology"
+            ]
+          },
+          "then": {
+            "properties": {
+              "familyMembers": {
+                "minItems": 1
+              }
+            }
+          }
+        }
+      ]
+    }
+  }
+}

